def bell_number(n):
    if n < 0:
        return 0
    elif n == 1:
        return 1
    B = [[0] * n for _ in range(n)]
    B[0][0] = 1

    for i in range(1, n):
        for row in range(n):
            B[i] = [0] * n
        B[0] = [1] * n
        for row in range(1, n):
            B[0][row] = B[0][row-1]
        for row in range(1, n):
            B[row] = [1] * n
        for row in range(1, n):
            for col in range(n):
                B[row][col] = B[row - 1][col - 1] + B[row - 1][col]
            B[0][row] = B[row][0]
        return B[n - 1][n - 1)
```

