def lps(s):
    def longest_pal_subsequence(s):
        n = len(s)
        dp = [[0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for l in range(2, n + 1):
            for start in range(n - l + 1):
                end = start + l - 1
                if l == 2:
                    if s[start] == s[end]:
                    dp[start][end] = 2
                else:
                    for innerLen in range(2, l + 1):
                        for start in range(n - innerLen + 1):
                        end = start + innerLen - 1
                        if l == innerLen:
                            if s[start] == s[end]:
                                dp[start][end] = 2
                            elif s[start] == s[end]:
                                for k in range(1, l - 1):
                                    dp[start][end] = max(dp[start][end], dp[start + k][end - k] + 1)
                                if k > 1:
                                    innerLen = l - 1
                            elif k > 0:
                                innerLen = l - 1
                            else:
                                innerLen = l
                for k in range(1, l):
                    dp[start][end] = max(dp[start][end], dp[start + k][end - k] + 1)
        return dp[0][n - 1]

    return longest_pal_subsequence(s)

